{
  "items": [
    {
      "name": "AddValuation.map_le_sum",
      "module_name": "Mathlib.RingTheory.Valuation.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} {Γ₀ : Type u_4} [inst : Ring R] [inst_1 : LinearOrderedAddCommMonoidWithTop Γ₀] (v : AddValuation R Γ₀)\n  {ι : Type u_6} {s : Finset ι} {f : ι → R} {g : Γ₀}, (∀ i ∈ s, g ≤ v (f i)) → g ≤ v (∑ i ∈ s, f i)"
    },
    {
      "name": "AddValuation.map_add'",
      "module_name": "Mathlib.RingTheory.Valuation.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} {Γ₀ : Type u_4} [inst : Ring R] [inst_1 : LinearOrderedAddCommMonoidWithTop Γ₀] (v : AddValuation R Γ₀)\n  (x y : R), v x ≤ v (x + y) ∨ v y ≤ v (x + y)"
    },
    {
      "name": "AddValuation.map_add",
      "module_name": "Mathlib.RingTheory.Valuation.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} {Γ₀ : Type u_4} [inst : Ring R] [inst_1 : LinearOrderedAddCommMonoidWithTop Γ₀] (v : AddValuation R Γ₀)\n  (x y : R), min (v x) (v y) ≤ v (x + y)"
    },
    {
      "name": "AddValuation",
      "module_name": "Mathlib.RingTheory.Valuation.Basic",
      "kind": "definition",
      "type": "(R : Type u_3) → [Ring R] → (Γ₀ : Type u_4) → [LinearOrderedAddCommMonoidWithTop Γ₀] → Type (max u_3 u_4)"
    },
    {
      "name": "AddValuation.of",
      "module_name": "Mathlib.RingTheory.Valuation.Basic",
      "kind": "definition",
      "type": "{R : Type u_3} →\n  {Γ₀ : Type u_4} →\n    [inst : Ring R] →\n      [inst_1 : LinearOrderedAddCommMonoidWithTop Γ₀] →\n        (f : R → Γ₀) →\n          f 0 = ⊤ →\n            f 1 = 0 →\n              (∀ (x y : R), min (f x) (f y) ≤ f (x + y)) → (∀ (x y : R), f (x * y) = f x + f y) → AddValuation R Γ₀"
    },
    {
      "name": "AddValuation.map_lt_sum",
      "module_name": "Mathlib.RingTheory.Valuation.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} {Γ₀ : Type u_4} [inst : Ring R] [inst_1 : LinearOrderedAddCommMonoidWithTop Γ₀] (v : AddValuation R Γ₀)\n  {ι : Type u_6} {s : Finset ι} {f : ι → R} {g : Γ₀}, g ≠ ⊤ → (∀ i ∈ s, g < v (f i)) → g < v (∑ i ∈ s, f i)"
    }
  ]
}
